import os, requests
os.chdir('/home/data4/xiangyu/BioDSA/workdir')
for q in ['Helicobacter pylori 2024 ACG guideline household members','ACG Clinical Guideline Treatment of Helicobacter pylori Infection 2024 Chey']:
 r=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi',params={'db':'pubmed','term':q,'retmode':'json','retmax':8},timeout=20)
 ids=r.json()['esearchresult']['idlist']
 print('\nQuery:',q,'PMIDs:',ids)
 if ids:
  x=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(ids),'retmode':'json'},timeout=20).json()['result']
  for i in ids: print(i,x[i].get('title'),x[i].get('pubdate'))
